//! Per-version game tables: packet ids, static registries, block states and
//! entity-data serializer ids.
//!
//! Each supported version has a module (`v26_3`) generated by
//! `cargo xtask codegen` from that version's official client jar: Mojang's
//! data generator reports for packets, registries and block states, and the
//! jar's bytecode for serializer ids. The generated files hold only facts
//! (names and numeric ids) and are committed, so building needs no game files.
//! The types they use are defined here and shared by every version.

#![forbid(unsafe_code)]

pub mod block;
pub mod registry;

pub mod v26_3;

/// Defines a fieldless enum whose discriminants are dense ids `0..n`, each
/// with the game's name for it. Used by the generated code.
///
/// The generator guarantees the variants are listed in id order, so
/// `ALL[id]` and `NAMES[id]` are the variant and name with that id.
macro_rules! id_enum {
    (
        $(#[$meta:meta])*
        $vis:vis enum $Name:ident: $repr:ident {
            $($Variant:ident = $id:literal => $name:literal,)+
        }
    ) => {
        $(#[$meta])*
        #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[repr($repr)]
        $vis enum $Name {
            $($Variant = $id,)+
        }

        impl $Name {
            /// Every value, in id order.
            pub const ALL: &'static [Self] = &[$(Self::$Variant,)+];

            /// The game's names, in id order.
            pub const NAMES: &'static [&'static str] = &[$($name,)+];

            /// The numeric id (what goes on the wire).
            pub const fn id(self) -> u32 {
                self as u32
            }

            /// The value with this id, if there is one.
            pub const fn from_id(id: u32) -> Option<Self> {
                if (id as usize) < Self::ALL.len() {
                    Some(Self::ALL[id as usize])
                } else {
                    None
                }
            }

            /// The game's name, e.g. `minecraft:stone`.
            pub const fn name(self) -> &'static str {
                Self::NAMES[self as usize]
            }

            /// The value with this name, if there is one.
            pub fn from_name(name: &str) -> Option<Self> {
                match name {
                    $($name => Some(Self::$Variant),)+
                    _ => None,
                }
            }
        }

        impl ::core::fmt::Display for $Name {
            fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
                f.write_str(self.name())
            }
        }
    };
}
pub(crate) use id_enum;
